import React, { useEffect, useState } from 'react';
import { useLocation } from 'react-router-dom';
import { useDispatch } from 'react-redux';
import { logout } from '../store/authSlice';
import { supabaseService } from '../services/supabaseService';

const HoneypotTrap = () => {
    const location = useLocation();
    const dispatch = useDispatch();
    const [banned, setBanned] = useState(false);

    useEffect(() => {
        const triggerTrap = async () => {
            // Show the denied screen IMMEDIATELY
            setBanned(true);

            // FORCE LOCAL LOGOUT (Redux & Storage)
            dispatch(logout());

            // Run these in the background so they don't delay the UI
            Promise.all([
                supabaseService.logActivity('honeypot_triggered', {
                    path: location.pathname,
                    warning: 'Malicious route accessed. IP Ban Initiated.'
                }),
                supabaseService.triggerHoneypotBan(location.pathname)
            ]).catch(err => console.error('Honeypot background processing failed', err));
        };

        triggerTrap();
    }, [location.pathname]);

    if (banned) {
        return (
            <div className="min-h-screen bg-black flex items-center justify-center p-4">
                <div className="max-w-md w-full bg-slate-900 border-2 border-red-900 rounded-[2rem] p-8 md:p-12 text-center relative overflow-hidden shadow-[0_0_100px_rgba(220,38,38,0.2)]">
                    <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-red-600 to-transparent animate-pulse" />
                    
                    <h1 className="text-4xl font-black text-white mb-4 tracking-tighter italic">ACCESS DENIED</h1>
                    
                    <div className="space-y-4">
                        <p className="text-red-500 font-mono text-xs uppercase tracking-widest leading-relaxed">
                            Unauthorized system access detected.
                        </p>
                        <div className="h-px bg-gradient-to-r from-transparent via-red-900/50 to-transparent" />
                        <p className="text-slate-500 text-[10px] leading-relaxed uppercase font-bold tracking-tight">
                            Incidents are logged. IP blacklisted.
                        </p>
                    </div>
                </div>
            </div>
        );
    }

    return <div className="min-h-screen bg-black"></div>;
};

export default HoneypotTrap;
